         var sessions = new SessionApplicationService(runtime);
         var server = new AcpV1Server(System.in, stdout, sessions, permissions,
                 new PromptApplicationService(sessions, new MemoryHostStore()), model(environment))) {
        server.run();
    }
    return 0;

